INSERT INTO repo_kcrs (kcr_id, name, domain, concept_category, concept_type, definition, scope, core_principles, semantic_description, keywords_synonyms, status) VALUES ('KCR_000501', 'product data exchange', 'Engineering & Technology', 'CAD/CAM', 'Technical Concept', 'Transferring product geometry and engineering information between different CAD/CAM systems using defined data formats.', 'Applies to the analysis, design, implementation, interpretation, or evaluation of product data exchange within CAD/CAM, particularly where the CAD/CAM Integration and Product Data module establishes its technical context.', 'Core considerations include the defining characteristics of product data exchange, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'Transferring product geometry and engineering information between different CAD/CAM systems using defined data formats. Within CAD/CAM Integration and Product Data, the concept covers Applies to the analysis, design, implementation, interpretation, or evaluation of product data exchange within CAD/CAM, particularly where the CAD/CAM Integration and Product Data module establishes its technical context. Key technical considerations are Core considerations include the defining characteristics of product data exchange, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it.', 'product data exchange; Core considerations include the defining characteristics of product data exchange, its governing relationships or mechanisms, applicable assumptions and constraints, and criteria used to analyse or evaluate it; CAD/CAM', 'Active'), ('KCR_000502', 'Product Lifecycle Management (PLM)', 'Engineering & Technology', 'CAD/CAM', 'Technical Concept', 'Product Lifecycle Management, the controlled management of product information and processes from design through manufacture, service, and retirem